// src/lib/runProcess.ts
import { execa } from "execa";
import pc from "picocolors";
function prefixStream(label, color, chunk, isError) {
  const tag = color(`[${label}]`);
  const text = chunk.toString("utf8");
  for (const line of text.split("\n")) {
    if (line.length === 0) continue;
    const out = `${tag} ${line}`;
    if (isError) process.stderr.write(out + "\n");
    else process.stdout.write(out + "\n");
  }
}
async function runConcurrent(specs) {
  const children = [];
  let shuttingDown = false;
  let exitCode = 0;
  const shutdown = () => {
    if (shuttingDown) return;
    shuttingDown = true;
    for (const child of children) {
      child.kill("SIGTERM");
    }
  };
  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);
  const runs = specs.map((spec) => {
    const child = execa(spec.command, spec.args, {
      cwd: spec.cwd,
      env: { ...process.env, FORCE_COLOR: "1", ...spec.env },
      stdout: "pipe",
      stderr: "pipe",
      reject: false
    });
    children.push(child);
    child.stdout?.on("data", (c) => prefixStream(spec.label, spec.color, c, false));
    child.stderr?.on("data", (c) => prefixStream(spec.label, spec.color, c, true));
    return child.then((result) => {
      const code = typeof result.exitCode === "number" ? result.exitCode : 0;
      if (code !== 0 && !shuttingDown) {
        process.stderr.write(pc.red(`[${spec.label}] exited with code ${code}
`));
        exitCode = code;
      }
      shutdown();
    });
  });
  await Promise.all(runs);
  process.off("SIGINT", shutdown);
  process.off("SIGTERM", shutdown);
  return exitCode;
}
async function runOnce(command, args, cwd, env = {}) {
  const result = await execa(command, args, {
    cwd,
    env: { ...process.env, ...env },
    stdio: "inherit",
    reject: false
  });
  return typeof result.exitCode === "number" ? result.exitCode : 0;
}

